/**
 * NEXUS ESPORTS — Super Admin · Add administrator
 *
 * Elevates an existing account, or creates a new staff account with a
 * one-time password generated by the server and shown here once.
 */
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { AuthAPI } from '../../services/api.js';
import { ADMIN_ROLE_OPTIONS } from '../../lib/adminRoles.js';
import { Notice, PageHeader, copyText } from '../../components/ui.jsx';
import UsernameSearch from '../../components/UsernameSearch.jsx';
import { showToast } from '../../lib/toast.js';

export default function AddAdmin() {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [adminType, setAdminType] = useState('admin');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState(null);

  async function onSubmit(event) {
    event.preventDefault();
    setError('');
    const name = username.trim().replace(/^@/, '');
    if (!name) { setError('Enter a username or email.'); return; }
    setSubmitting(true);
    const res = await AuthAPI.addAdmin(name, adminType, email.trim() || undefined);
    setSubmitting(false);
    if (!res.ok) { setError(res.error || 'The administrator was not saved.'); return; }
    setResult(res.data);
    setUsername('');
    setEmail('');
    showToast(`@${res.data.user.username} now has ${adminType.replace(/_/g, ' ')} access.`);
  }

  return (
    <main className="main-content">
      <Link to="/pages/super-admin/admins.html" className="back-btn-alt">← Back to admins</Link>
      <PageHeader title="Add administrator" subtitle="Give an existing account a staff role, or create a new staff account." />

      {result?.created && (
        <Notice tone="success">
          Account @{result.user.username} was created. One-time password: <code style={{ color: '#fff', letterSpacing: 1 }}>{result.temporaryPassword}</code>{' '}
          <button type="button" className="btn-table-secondary" onClick={async () => showToast((await copyText(result.temporaryPassword)) ? 'Copied.' : 'Copy failed.')}>Copy</button>
          <br />It is shown only once. Share it privately; they should change it from their profile.
        </Notice>
      )}
      {result && !result.created && <Notice tone="success">@{result.user.username} was elevated. They see their new dashboard after signing in again.</Notice>}

      <form className="ui-card" style={{ maxWidth: 640 }} onSubmit={onSubmit}>
        <div className="ui-field">
          <label htmlFor="admin-username">Username or email *</label>
          <UsernameSearch id="admin-username" value={username} onChange={setUsername} onPick={setUsername} scope="all" showRole placeholder="Search an account, or type a new username" />
          <span className="ui-field-help">Pick an existing account to elevate it, or type a new username to create a staff account.</span>
        </div>
        <div className="ui-field">
          <label htmlFor="admin-email">Email for a new account (optional)</label>
          <input id="admin-email" className="form-input" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Defaults to username@nexus.gg" />
        </div>
        <div className="ui-field">
          <label htmlFor="admin-type">Role *</label>
          <select id="admin-type" className="form-input" value={adminType} onChange={(e) => setAdminType(e.target.value)}>
            {ADMIN_ROLE_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
          </select>
        </div>
        {error && <Notice tone="danger">{error}</Notice>}
        <div className="ui-dialog-actions">
          <Link className="btn-cancel" to="/pages/super-admin/admins.html">Cancel</Link>
          <button type="submit" className="btn-primary" disabled={submitting}>{submitting ? 'Saving…' : 'Grant access'}</button>
        </div>
      </form>
    </main>
  );
}
